'use strict';
// Nightly. For each agent, how many ratings their tickets received in the past seven days and the average score.
// Saved through the store; agents without ratings in the window get no row.
const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyRatingSummary(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.rating_score == null || !t.owner_id) continue;
    if (new Date(t.rated_at).getTime() < since) continue;
    const s = byAgent.get(t.owner_id) || { ratings: 0, sum: 0 };
    s.ratings += 1;
    s.sum += t.rating_score;
    byAgent.set(t.owner_id, s);
  }
  const rows = [...byAgent]
    .map(([agent_id, s]) => ({ agent_id, ratings: s.ratings, average: Math.round((s.sum / s.ratings) * 100) / 100 }))
    .sort((a, b) => a.agent_id - b.agent_id);
  const summary = { week_ending: now.toISOString(), rows };
  store.saveRatingSummary(summary);
  return summary;
}

module.exports = { weeklyRatingSummary, WINDOW_DAYS };
```

